head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[session > M > setAttribute]<br/>브라우저 세션에 데이터를 저장합니다. 동일한 key 파라미터로 이미 값이 존재하면 덮어쓰기됩니다.",
    "validation" : [
        "key(필수) 파라미터로 세션 데이터를 저장할 키를 설정할 수 있어야 합니다.",
        "value(필수) 파라미터로 세션에 저장할 값을 설정할 수 있어야 합니다.",
        "String, XML Document, Object 타입의 데이터를 저장할 수 있어야 합니다.",
        "XML Document 타입은 저장 시 자동으로 직렬화되고, getAttribute() 메소드로 조회 시 자동으로 파싱되어 반환되어야 합니다.",
        "동일한 key 파라미터로 이미 값이 존재하면 덮어쓰기되어야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_setAttribute_onclick = function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1 : String 값 저장
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : String 값 저장 (key='userName', value='Hong') ──");

        WebSquare.session.setAttribute("userName", "Hong");

        var result = WebSquare.session.getAttribute("userName");
        wf_body_bottom.getObj("scwin").setReturnValue("getAttribute('userName') : 반환 타입=" + (typeof result) + " / 반환값='" + result + "'");
    } else if (scenario === "2") {
        // 시나리오 2 : Object 값 저장
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : Object 값 저장 (key='config', value={theme:'dark', lang:'ko'}) ──");

        WebSquare.session.setAttribute("config", { theme: "dark", lang: "ko" });

        var result = WebSquare.session.getAttribute("config");
        wf_body_bottom.getObj("scwin").setReturnValue("getAttribute('config') : 반환 타입=" + (typeof result) + " / 반환값=" + JSON.stringify(result));
    } else if (scenario === "3") {
        // 시나리오 3 : XML Document 저장 → 자동 직렬화/파싱
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : XML Document 저장 (자동 직렬화 / 조회 시 자동 파싱) ──");

        var xmlDoc = WebSquare.xml.parse("<book><title>Harry Potter</title><price>29.99</price></book>");
        WebSquare.session.setAttribute("xmlData", xmlDoc);

        var result = WebSquare.session.getAttribute("xmlData");
        wf_body_bottom.getObj("scwin").setReturnValue("getAttribute('xmlData') : 반환 타입=" + (typeof result) + " / nodeType=" + (result ? result.nodeType : "null"));
        if (result) {
            var serialized = WebSquare.xml.serialize(result);
            wf_body_bottom.getObj("scwin").setReturnValue("XML 직렬화 : " + serialized.replace(/\s+/g, " ").replace(/>\s+</g, "><"));
        }
    } else if (scenario === "4") {
        // 시나리오 4 : 동일 key 덮어쓰기
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 4 : 동일 key 덮어쓰기 (key='userName') ──");

        WebSquare.session.setAttribute("userName", "Hong");
        wf_body_bottom.getObj("scwin").setReturnValue("1차 저장 후 getAttribute('userName') : '" + WebSquare.session.getAttribute("userName") + "'");

        WebSquare.session.setAttribute("userName", "Kim");
        wf_body_bottom.getObj("scwin").setReturnValue("2차 저장(덮어쓰기) 후 getAttribute('userName') : '" + WebSquare.session.getAttribute("userName") + "'");
    }
};
